@Component({
  selector: 'app-transfer-form',
  imports: [ReactiveFormsModule, CurrencyPipe],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './transfer-form.component.html',   // [formGroup], (ngSubmit)="submit()", [disabled]="saving()"
