export class TransferFormComponent {
  private readonly api = inject(PaymentsApi);
  private readonly destroyRef = inject(DestroyRef);
  readonly account = input.required<Account>();                       // signal input
  readonly submitted = output<PaymentReceipt>();                      // event to parent
  readonly saving = signal(false);
  readonly available = computed(() => this.account().balance - this.account().pendingDebits);   // replaces ngOnChanges logic

  readonly form = new FormGroup({
    amount: new FormControl<number | null>(null, [Validators.required, Validators.min(0.01)]),
    payeeId: new FormControl('', { nonNullable: true, validators: [Validators.required] }),
  });

  constructor() {
    afterNextRender(() => document.getElementById('amount')?.focus());   // DOM work, SSR-safe
  }

  submit(): void {
    if (this.form.invalid) return;
    this.saving.set(true);
    this.api.create(this.account().id, this.form.getRawValue())
      .pipe(takeUntilDestroyed(this.destroyRef), finalize(() => this.saving.set(false)))
      .subscribe(receipt => this.submitted.emit(receipt));
  }
}
