export class PortfolioState {
  readonly positions = signal<Position[]>([]);
  readonly fxRates = signal<Record<string, number>>({});
  readonly baseCurrency = signal('GBP');

  // Derived state: computed, never effect
  readonly totalValue = computed(() => {
    const rates = this.fxRates(); const base = this.baseCurrency();
    return this.positions().reduce((sum, p) => sum + p.quantity * p.price * (rates[p.currency + base] ?? 1), 0);
  });

  // Selection resets when positions are replaced (e.g. account switch)
  readonly selectedId = linkedSignal(() => this.positions()[0]?.id ?? null);

  constructor() {
    // Side effect: persist user preference; untracked avoids depending on positions
    effect(() => {
      const base = this.baseCurrency();
      untracked(() => localStorage.setItem('baseCurrency', base));
    });
  }

  addPosition(p: Position) { this.positions.update(list => [...list, p]); }   // immutable update
}
