      exhaustMap(() => {                                                // ignore clicks while a request is in flight
        this.status.set('sending');
        return this.api.create(this.payment(), this.idempotencyKey).pipe(
          tap(() => this.status.set('done')),
          catchError(() => { this.status.set('error'); return EMPTY; }) // keep the outer stream alive
        );
      }),
      takeUntilDestroyed(),
    ).subscribe();
  }

  pay() { this.clicks.next(); }
}

