export const correlationInterceptor: HttpInterceptorFn = (req, next) =>
  next(req.clone({ setHeaders: { 'X-Request-Id': crypto.randomUUID() } }));

export const csrfInterceptor: HttpInterceptorFn = (req, next) => {
  const isApi = req.url.startsWith('/bff/');
  return next(isApi ? req.clone({ withCredentials: true, setHeaders: { 'X-CSRF': '1' } }) : req);
};

export const retryInterceptor: HttpInterceptorFn = (req, next) =>
  req.method !== 'GET' ? next(req) : next(req).pipe(
    retry({ count: 2, delay: (err, attempt) => (err instanceof HttpErrorResponse && (err.status === 0 || err.status === 503))
      ? timer(250 * 2 ** attempt + Math.random() * 100) : throwError(() => err) }),
  );

export const errorInterceptor: HttpInterceptorFn = (req, next) => {
  const router = inject(Router); const notify = inject(NotificationService);
  return next(req).pipe(
    timeout(15000),
    catchError((err: unknown) => {
      if (err instanceof HttpErrorResponse) {
        if (err.status === 401) router.navigateByUrl('/session-expired');
        else if (err.status === 429) notify.warn('Too many requests. Please wait a moment.');
        else if (err.status >= 500) notify.error('Something went wrong. Reference: ' + (err.headers.get('X-Request-Id') ?? 'n/a'));
        return throwError(() => AppError.fromHttp(err));                  // typed problem details for components
      }
      return throwError(() => err);
    }),
  );
};
