export function withinAvailable(available: () => number): ValidatorFn {
  return (group: AbstractControl) => {
    const amount = (group as PaymentForm).controls.amount.value ?? 0;
    return amount > available() ? { exceedsAvailable: { available: available() } } : null;
  };
