export function ibanValidator(api: IbanApi): AsyncValidatorFn {
  return control => timer(300).pipe(                                   // debounce-like delay
    switchMap(() => api.validate(control.value)),
    map(r => (r.valid ? null : { iban: r.reason })),
    catchError(() => of(null)),                                        // don't block on validator outage; server re-validates
  );
}

