// Per-row signals updated from batched ticks; only changed rows refresh
export interface GridRow { id: string; symbol: string; price: WritableSignal<number>; change: WritableSignal<number>; }

@Injectable()
export class QuoteGridStore {
  private readonly rows = new Map<string, GridRow>();
  readonly order = signal<string[]>([]);                                  // row ids in display order
  private pending = new Map<string, Tick>();
  private scheduled = false;

  constructor() {
    const worker = new Worker(new URL('./quotes.worker', import.meta.url), { type: 'module' });   // parse WebSocket off main thread
    worker.onmessage = ({ data }: MessageEvent<Tick[]>) => this.enqueue(data);
    inject(DestroyRef).onDestroy(() => worker.terminate());
  }

  row(id: string) { return this.rows.get(id)!; }

  private enqueue(ticks: Tick[]) {
    for (const t of ticks) this.pending.set(t.id, t);                    // keep latest per symbol
    if (this.scheduled) return;
    this.scheduled = true;
    requestAnimationFrame(() => {                                        // apply once per frame
      for (const t of this.pending.values()) {
        const row = this.rows.get(t.id);
        if (row) { row.change.set(t.price - row.price()); row.price.set(t.price); }
      }
      this.pending.clear(); this.scheduled = false;
    });
  }
}
// Template: <cdk-virtual-scroll-viewport itemSize="32"> *cdkVirtualFor="let id of store.order()" -> <app-quote-row [row]="store.row(id)" /> (OnPush)
