@Injectable({ providedIn: 'root' })
export class NotificationsHub {
  private readonly payments = inject(PaymentsStore);
  private readonly api = inject(PaymentsApi);
  readonly connected = signal(false);
  private lastVersion = 0;

  private readonly connection = new HubConnectionBuilder()
    .withUrl('/bff/hubs/notifications')                                   // same-origin cookie auth via BFF
    .withAutomaticReconnect([0, 2000, 5000, 10000, 30000])
    .build();

  constructor() {
    this.connection.on('paymentStatusChanged', (e: PaymentStatusEvent) => {
      if (e.version <= this.lastVersion) return;                          // ignore stale or duplicate
      this.lastVersion = e.version;
      this.payments.applyStatus(e.paymentId, e.status, e.version);
    });
    this.connection.onreconnecting(() => this.connected.set(false));
    this.connection.onreconnected(async () => {
      this.connected.set(true);
      const changes = await firstValueFrom(this.api.changesSince(this.lastVersion));   // recover missed updates
      changes.forEach(c => this.payments.applyStatus(c.paymentId, c.status, c.version));
    });
  }

  async start() { await this.connection.start(); this.connected.set(true); }
}
