// Journey instrumentation: start, success and failure events with release and route context
@Injectable({ providedIn: 'root' })
export class JourneyTracker {
  private readonly telemetry = inject(Telemetry);
  private readonly active = new Map<string, number>();

  start(journey: 'payment' | 'login' | 'statement-download') {
    const id = crypto.randomUUID(); this.active.set(id, performance.now());
    this.telemetry.event('journey_start', { journey, id, release: APP_VERSION });
    return id;
  }
  succeed(id: string, journey: string) { this.end(id, journey, 'success'); }
  fail(id: string, journey: string, reason: 'client_error' | 'api_error' | 'abandoned') { this.end(id, journey, reason); }

  private end(id: string, journey: string, outcome: string) {
    const started = this.active.get(id); this.active.delete(id);
    this.telemetry.event('journey_end', { journey, id, outcome, durationMs: started ? Math.round(performance.now() - started) : null, release: APP_VERSION });
  }
}
