// Queue submissions offline in IndexedDB and sync with idempotency keys when online
@Injectable({ providedIn: 'root' })
export class SubmissionQueue {
  private readonly db = inject(OfflineDb);                    // Dexie or idb wrapper, encrypted fields
  private readonly api = inject(ApplicationsApi);
  readonly pending = signal(0);

  async enqueue(app: MortgageApplicationDraft) {
    await this.db.outbox.put({ id: app.id, idempotencyKey: app.id + ':' + app.version, payload: await encryptForDevice(app), createdAt: Date.now() });
    this.pending.set(await this.db.outbox.count());
    if (navigator.onLine) await this.flush();
  }

  async flush() {
    for (const item of await this.db.outbox.toArray()) {
      try {
        await firstValueFrom(this.api.submit(await decryptForDevice(item.payload), item.idempotencyKey));
        await this.db.outbox.delete(item.id);                  // remove local copy after server acceptance
      } catch (e) {
        if (isConflict(e)) await this.db.markNeedsReview(item.id); else break;   // stop on network errors; retry later
      }
    }
    this.pending.set(await this.db.outbox.count());
  }
}
