export default function migrateButtonVariant(): Rule {
  return (tree: Tree) => {
    tree.visit(path => {
      if (!path.endsWith('.html')) return;
      const content = tree.read(path)?.toString('utf-8');
      if (!content?.includes('ds-button')) return;
      // v5 -> v6: [primary]="true" attribute replaced by variant="primary"
